public voidYaf_Plugin_Abstract::postDispatch Yaf_Request_Abstractrequest Yaf_Response_Abstractresponse
Este gancho é acionado após o término de cada iteração de despacho, isto é, após a execução da ação. Assim como Yaf_Plugin_Abstract::preDispatch, pode ser chamado mais de uma vez por requisição.

  &reftitle.examples;

   Exemplo de Yaf_Plugin_Abstract::postDispatch


<?php
class BenchmarkPlugin extends Yaf_Plugin_Abstract
{
    public function postDispatch(Yaf_Request_Abstract $request, Yaf_Response_Abstract $response)
    {
        /* a ação foi executada: acrescenta algumas
         * informações de depuração ao corpo da resposta */
        $elapsed = microtime(true) - Yaf_Registry::get("request_start");
        $response->appendBody(sprintf(
            "\n<!-- rendered in %.3f seconds -->",
            $elapsed
        ));
    }
}

/* os plugins são registrados no bootstrap */
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initPlugin(Yaf_Dispatcher $dispatcher)
    {
        $dispatcher->registerPlugin(new BenchmarkPlugin());
    }
}
?>
